def collectAllKeys(grid):
    rows, cols = len(grid), len(grid[0])
    m = 0
    start = (0, 0)
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v == 2:
                start = (r, c)
            elif 10 <= v < 20:
                m += 1
    full = (1 << m) - 1
    nm = 1 << m
    seen = bytearray(rows * cols * nm)
    seen[(start[0] * cols + start[1]) * nm] = 1
    frontier = [(start[0], start[1], 0)]
    steps = 0
    while frontier:
        steps += 1
        nxt = []
        for r, c, mask in frontier:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < rows and 0 <= nc < cols):
                    continue
                v = grid[nr][nc]
                if v == 1:
                    continue
                if 20 <= v < 30 and not (mask >> (v - 20)) & 1:
                    continue
                new = mask | (1 << (v - 10)) if 10 <= v < 20 else mask
                if new == full:
                    return steps
                idx = (nr * cols + nc) * nm + new
                if not seen[idx]:
                    seen[idx] = 1
                    nxt.append((nr, nc, new))
        frontier = nxt
    return -1
